import { COVER_VERSIONS } from "./cover-versions";

/** App shelf thumbnail — synced from moonpage-app on each build. */
export function storyCoverSrc(file: string): string {
  const v = COVER_VERSIONS[file];
  return v ? `/covers/${file}?v=${v}` : `/covers/${file}`;
}

/** Absolute URL for JSON-LD and Open Graph. */
export function storyCoverUrl(domain: string, file: string): string {
  return `${domain}${storyCoverSrc(file)}`;
}

/**
 * 480px sibling of a cover, generated by scripts/gen-cover-variants.mjs.
 * Used for narrow slots (search result thumbnails) and as the small entry in
 * the grid srcSet. The cache-busting `v` is shared with the original so a
 * cover change invalidates both at once.
 */
export function coverVariantSrc(file: string): string {
  const v = COVER_VERSIONS[file];
  const base = `/covers/${file.replace(/\.webp$/, "-480.webp")}`;
  return v ? `${base}?v=${v}` : base;
}

/**
 * Real width descriptors for static-export covers. Without these, `sizes`
 * is inert: the browser has only one candidate and downloads it regardless
 * of the slot. 800w remains the high-DPI / wide-column candidate.
 */
export function storyCoverSrcSet(file: string): string {
  return `${coverVariantSrc(file)} 480w, ${storyCoverSrc(file)} 800w`;
}
